const show=()=>{world.textContent='Choose the boundary, then run the crash scenario.'};run.onclick=()=>{const transactional=tx.checked,strict=committed.checked;const physical=2;const aborted=transactional?1:0;const visible=transactional&&strict?1:2;world.textContent='Input: offset 10
Crash: after first output send, before normal completion
Mode: '+(transactional?'transactional output + offset':'independent output then offset')+'
Physical output attempts in toy log: '+physical+'
Aborted transactional attempts: '+aborted+'
Visible outputs to this consumer: '+visible+'
Committed next input offset: 11
Result: '+(visible===1?'one committed result is observed':'duplicate/aborted attempt is observable')};[tx,committed].forEach(e=>e.oninput=show);show();
function drawMechanism(){const t=tx.checked,c=committed.checked,done=world.textContent.includes('Physical output');mechanism.innerHTML='<p>One input: <strong>offset 10</strong>. Both attempts produce the same derived edge.</p><div class="mv-grid"><div class="mv-box"><strong>Attempt 1 → crash</strong><p>Output edge E1: '+(t?'ABORTED transaction':'independently saved')+'</p><p>Input bookmark: still 10</p></div><div class="mv-box"><strong>Restart → attempt 2</strong><p>Reads input 10 again; writes edge E2.</p><p>'+ (t?'COMMIT E2 and bookmark 11 together':'save E2, then bookmark 11')+'</p></div></div><p>↓ Output log retains two physical attempts in this toy</p><div class="mv-row"><span class="mv-chip">E1 · '+(t?'ABORTED':'saved')+'</span><span class="mv-chip">E2 · COMMITTED</span></div><p>↓ Reader filter: '+(c?'read committed':'read uncommitted')+'</p><div class="mv-box"><strong>Visible to downstream: '+(t&&c?'E2 only':'E1 + E2')+'</strong><p>'+ (t&&c?'The aborted attempt is hidden. One committed result is observed.':'The first attempt remains observable. A transaction alone needs the matching reader isolation.')+'</p></div><p class="mv-note">'+(done?'Executed crash/restart toy shown above.':'Preview the selected boundary; press Run to execute the crash/restart toy.')+'</p>'; }
[tx,committed,run].forEach(el=>{for(const event of ['onclick','oninput']){const original=el[event];if(original)el[event]=function(...args){const result=original.apply(this,args);drawMechanism();return result}}});drawMechanism();

const show=()=>{const wire=reuse.checked?{1:'orders',2:'30',3:'restricted'}:{1:'orders',2:'team-a',3:'restricted'};const old={dataset_id:wire[1],owner:wire[2]},unknown=jsonBridge.checked?{}:{3:wire[3]};const forwarded={1:old.dataset_id,2:old.owner,...unknown};const newest=reuse.checked?{dataset_id:forwarded[1],retention_days:forwarded[2],classification:forwarded[3]||'(lost)'}:{dataset_id:forwarded[1],owner:forwarded[2],classification:forwarded[3]||'(lost)'};world.textContent='Wire tags: '+JSON.stringify(wire)+'
Old V1 interpretation: '+JSON.stringify(old)+'
Relay path: '+(jsonBridge.checked?'known fields through JSON; unknown tag dropped':'binary message copy; unknown tag preserved')+'
Newest interpretation after relay: '+JSON.stringify(newest)+'
Assessment: '+(reuse.checked?'UNSAFE — tag 2 has two meanings during mixed deployment':jsonBridge.checked?'wire-safe schema, lossy relay path':'safe additive evolution in this model')};[jsonBridge,reuse].forEach(e=>e.oninput=show);show();
function drawMechanism(){const bridge=jsonBridge.checked,reused=reuse.checked;mechanism.innerHTML='<p>Follow the same numbered fields through an older relay.</p><table><thead><tr><th>Tag</th><th>Incoming meaning</th><th>Old relay</th><th>Forwarded</th></tr></thead><tbody><tr><td>1</td><td>dataset_id = orders</td><td>known → copied</td><td>orders</td></tr><tr><td>2</td><td>'+(reused?'retention_days = 30':'owner = team-a')+'</td><td>reads as OWNER</td><td>'+(reused?'30 under a conflicting meaning':'team-a')+'</td></tr><tr><td>3</td><td>classification = restricted</td><td>unknown → '+(bridge?'DROPPED':'preserved')+'</td><td>'+(bridge?'✕ missing':'restricted')+'</td></tr></tbody></table><p>↓ '+(bridge?'Rebuild from known fields only: tag 3 has no destination.':'Binary parse/reserialize: unknown tag 3 stays attached.')+'</p><p class="mv-note">'+(reused?'Tag 2 passes through, but old and new services disagree on its meaning. Successful parsing does not make reuse safe.':bridge?'The schema change is additive, but this relay loses data. Keep the original binary message or explicitly preserve all needed fields.':'The new reader receives tag 3 even though the old relay did not understand it.')+'</p>'; }
[jsonBridge,reuse].forEach(el=>{for(const event of ['onclick','oninput']){const original=el[event];if(original)el[event]=function(...args){const result=original.apply(this,args);drawMechanism();return result}}});drawMechanism();

const show=()=>{const n=+zones.value,p=+perZone.value,normal=n*p,surviving=(n-1)*p,deficit=Math.max(0,100-surviving),stable=deficit===0;world.textContent='Normal provisioned capacity: '+normal+'% of demand
After one zone loss: '+surviving+'% remains
Immediate deficit: '+deficit+'%
Control plane: '+(control.checked?'available in this scenario':'unavailable')+'
Outcome: '+(stable?'STATICALLY STABLE — existing capacity carries demand':control.checked?'REACTIVE RECOVERY REQUIRED — depends on successful mutation':'CAPACITY OUTAGE — no recovery mutation available')+'

Survival test: (zones − 1) × per-zone capacity ≥ 100'};[zones,perZone,control].forEach(e=>e.oninput=show);show();
function drawMechanism(){const n=+zones.value,p=+perZone.value,s=(n-1)*p,gap=Math.max(0,100-s),scale=350;mechanism.innerHTML='<div class="mv-row">'+Array.from({length:n},(_,i)=>'<span class="mv-chip">Zone '+(i+1)+': '+(i===n-1?'✕ LOST':p+'% available')+'</span>').join('')+'</div><p>Capacity after one loss: <strong>'+s+'% of demand</strong>. All bars use the same 0–350% scale.</p><div style="position:relative;padding-bottom:25px"><div class="mv-bar"><span style="width:'+(s/scale*100)+'%"></span></div><span style="position:absolute;left:'+(100/scale*100)+'%;top:0;height:25px;border-left:3px solid #ffdf96"></span><span style="position:absolute;left:0;top:27px">0%</span><span style="position:absolute;left:24%;top:27px">100% needed</span><span style="position:absolute;right:0;top:27px">350%</span></div><p style="margin-top:22px">'+(gap?'Missing '+gap+' percentage points → must provision more.':'Already enough → continue serving while repair waits.')+'</p><div class="mv-box"><strong>Emergency provisioning gate: '+(control.checked?'AVAILABLE':'BLOCKED')+'</strong><p>'+(gap?(control.checked?'Recovery may create capacity, but useful service currently depends on that change succeeding.':'The missing capacity cannot be created; the workload has a capacity outage.'):'Existing capacity does not need this gate to pass the modeled failure.')+'</p></div>'; }
[zones,perZone,control].forEach(el=>{for(const event of ['onclick','oninput']){const original=el[event];if(original)el[event]=function(...args){const result=original.apply(this,args);drawMechanism();return result}}});drawMechanism();

let progress=0,events=[],brain=true,hand=true,log=[];const show=()=>world.textContent='Mode: '+mode.value+'
Brain: '+(brain?'running':'failed')+'; hand: '+(hand?'running':'failed')+'
Recovered progress: '+progress+'/3
Durable session events: '+events.length+'

'+log.join('
');const lose=what=>{if(mode.value==='coupled'){progress=0;events=[];log=['Coupled '+what+' failed: local progress unavailable']}else log.push(what+' failed; external session remains')};work.onclick=()=>{if(!brain||!hand){log.push('Cannot work until both components run')}else if(progress<3){progress++;if(mode.value==='decoupled')events.push({checkpoint:progress});log.push('Completed checkpoint '+progress+(mode.value==='decoupled'?'; event emitted':' only in local container'))}show()};failHand.onclick=()=>{hand=false;lose('hand');show()};failBrain.onclick=()=>{brain=false;lose('brain');show()};resume.onclick=()=>{brain=true;hand=true;if(mode.value==='decoupled')progress=events.length;log.push('Reprovisioned runtimes; resumed from '+progress);show()};reset.onclick=()=>{progress=0;events=[];brain=true;hand=true;log=[];show()};mode.oninput=reset.onclick;show();
function drawMechanism(){const durable=mode.value==='decoupled';mechanism.innerHTML='<div class="mv-grid"><div class="mv-box mv-dashed"><strong>Replaceable runtimes</strong><p>Brain: '+(brain?'RUNNING':'✕ FAILED')+'</p><p>Hand / sandbox: '+(hand?'RUNNING':'✕ FAILED')+'</p><p>Working progress: '+progress+'/3</p>'+(!durable?'<p>Local-only checkpoints: '+progress+'<br>Runtime failure removes this record.</p>':'<p>Completed checkpoint → write an external event.</p>')+'</div><div class="mv-box"><strong>Outside the runtime</strong>'+(durable?'<p>Durable session:</p><div class="mv-row">'+(events.map(e=>'<span class="mv-chip">✓ checkpoint '+e.checkpoint+'</span>').join('')||'<em>No saved events yet</em>')+'</div><p>Resume ← read the saved events</p>':'<p>No external session exists. A replacement cannot recover erased local progress.</p>')+'</div></div><p class="mv-note">'+(!brain||!hand?'Failure is active. Compare the dashed runtime with the external session, then Resume.':'Complete two checkpoints, fail either runtime, then Resume. Does checkpoint 2 survive?')+'</p>'; }
[mode,work,failHand,failBrain,resume,reset].forEach(el=>{for(const event of ['onclick','oninput']){const original=el[event];if(original)el[event]=function(...args){const result=original.apply(this,args);drawMechanism();return result}}});drawMechanism();

const rewardPolicy=[.85,.10,.05],target=[.50,.30,.20],rewards=[1,.7,.4];const show=()=>{const t=+mix.value/100,p=rewardPolicy.map((x,i)=>(1-t)*x+t*target[i]),expected=p.reduce((s,x,i)=>s+x*rewards[i],0),l1=p.reduce((s,x,i)=>s+Math.abs(x-target[i]),0),entropy=-p.reduce((s,x)=>s+(x?x*Math.log2(x):0),0);world.textContent='Modes: straightforward | memory-efficient | parallel
Current distribution: '+p.map(x=>(x*100).toFixed(0)+'%').join(' | ')+'
Target distribution: 50% | 30% | 20%
Expected scalar reward: '+expected.toFixed(3)+'
L1 distance to target: '+l1.toFixed(3)+'
Output-mode entropy: '+entropy.toFixed(3)+' bits

This objective calculator is not MaD-RL.'};mix.oninput=show;show();
function drawMechanism(){const t=+mix.value/100,p=rewardPolicy.map((x,i)=>(1-t)*x+t*target[i]),names=['Straightforward','Memory-efficient','Parallel'];mechanism.innerHTML='<p>Compare each pair on a shared 0–100% scale. Bars are proportions of all generated solutions.</p>'+p.map((x,i)=>'<div><strong>'+names[i]+'</strong><p>Observed '+(x*100).toFixed(0)+'%</p><div class="mv-bar"><span style="width:'+(x*100)+'%"></span></div><p>Target '+(target[i]*100)+'%</p><div class="mv-bar" style="border-style:dashed"><span style="width:'+(target[i]*100)+'%;background:#9f8957"></span></div><p>Gap: '+((x-target[i])*100>0?'+':'')+((x-target[i])*100).toFixed(0)+' percentage points</p></div>').join('')+'<p class="mv-note">Moving toward the target reduces the excess straightforward share and fills the two missing styles. This slider interpolates a distribution; it does not train a model.</p>'; }
[mix].forEach(el=>{for(const event of ['onclick','oninput']){const original=el[event];if(original)el[event]=function(...args){const result=original.apply(this,args);drawMechanism();return result}}});drawMechanism();
